package com.example.placement;

import android.app.*;import android.os.Bundle;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.content.ContextCompat;import java.util.*;

/** Shared native view helpers used by the student screens. */
public abstract class BaseActivity extends AppCompatActivity {
 protected LinearLayout root,body; protected String title="PlaceMate";
 protected int blue=Color.rgb(200,16,46),navy=Color.rgb(158,16,40),ink=Color.rgb(32,33,36),muted=Color.rgb(98,102,109),bg=Color.rgb(247,247,248),line=Color.rgb(226,226,229),success=Color.rgb(33,134,83),warning=Color.rgb(183,121,31);
 protected abstract int layout();
 @Override protected void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(navy);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);setContentView(layout());root=findViewById(R.id.screenRoot);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);render();}
 protected abstract void render();
 protected int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
 protected TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
 protected LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 protected LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 protected LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
 protected void pad(View v,int a){v.setPadding(dp(a),dp(a),dp(a),dp(a));}
 protected GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 protected void card(LinearLayout into,View content){content.setBackground(shape(Color.WHITE,12,line));content.setElevation(dp(1));LinearLayout.LayoutParams p=lp(-1,-2);p.setMargins(0,dp(5),0,dp(7));into.addView(content,p);}
 protected void gap(LinearLayout into,int h){View v=new View(this);into.addView(v,lp(1,h));}
 protected void heading(LinearLayout into,String s){TextView t=text(s,19,ink,true);LinearLayout.LayoutParams p=lp(-1,-2);p.setMargins(0,dp(14),0,dp(6));into.addView(t,p);}
 protected Button button(String label,boolean primary,Runnable r){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?Color.WHITE:blue);b.setBackground(shape(primary?blue:Color.WHITE,8,primary?blue:line));b.setMinHeight(dp(48));b.setOnClickListener(v->r.run());return b;}
 protected EditText input(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setTextSize(15);e.setHint(hint);e.setInputType(type);e.setPadding(dp(14),0,dp(14),0);e.setBackground(shape(Color.WHITE,8,line));e.setOnFocusChangeListener((view,focused)->e.setBackground(shape(Color.WHITE,8,focused?blue:line)));e.setMinHeight(dp(52));return e;}
 protected void toolbar(String name){LinearLayout r=row();r.setPadding(dp(12),0,dp(16),0);TextView back=text("<",22,navy,true);r.addView(back,lp(38,58));back.setGravity(Gravity.CENTER);back.setOnClickListener(v->finish());LinearLayout branding=column();branding.setGravity(Gravity.CENTER_VERTICAL);branding.addView(text("NMIMS Hyderabad",17,ink,true));branding.addView(text(name+"  |  Placement Portal",11,muted,false));r.addView(branding,new LinearLayout.LayoutParams(0,dp(58),1));TextView mark=text("NMIMS",11,blue,true);mark.setGravity(Gravity.CENTER);mark.setBackground(shape(0xfffcecef,6,0));r.addView(mark,lp(62,32));root.addView(r);View sep=new View(this);sep.setBackgroundColor(line);root.addView(sep,lp(-1,1));}
 protected void scroll(boolean bottom){ScrollView sc=new ScrollView(this);body=column();body.setPadding(dp(20),dp(12),dp(20),dp(24));sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 protected void label(LinearLayout l,String value){TextView t=text(value,13,muted,true);LinearLayout.LayoutParams p=lp(-1,-2);p.setMargins(0,dp(10),0,dp(5));l.addView(t,p);}
 protected void field(LinearLayout l,String label,String hint,int type){label(l,label);l.addView(input(hint,type),lp(-1,52));}
 protected void action(LinearLayout l,String label,Runnable r){Button b=button(label,true,r);LinearLayout.LayoutParams p=lp(-1,52);p.setMargins(0,dp(12),0,0);l.addView(b,p);}
 protected void link(LinearLayout l,String label,Runnable r){TextView t=text(label,14,blue,true);t.setGravity(Gravity.CENTER);t.setPadding(0,dp(14),0,dp(14));t.setOnClickListener(v->r.run());l.addView(t,lp(-1,-2));}
 protected void note(LinearLayout l,String s){TextView t=text(s,13,muted,false);t.setPadding(dp(12),dp(10),dp(12),dp(10));t.setBackground(shape(0xfffcecef,8,0));l.addView(t,lp(-1,-2));}
 protected void launch(Class<?> c){startActivity(new Intent(this,c));}
 protected void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 protected LinearLayout page(String title){toolbar(title);scroll(false);return body;}
 protected void item(LinearLayout list,String title,String sub,String right,Runnable click){LinearLayout c=column();pad(c,15);LinearLayout r=row();TextView a=text(title,16,ink,true);r.addView(a,new LinearLayout.LayoutParams(0,-2,1));if(right!=null)r.addView(text(right,11,statusColor(right),true));c.addView(r);if(sub!=null){TextView b=text(sub,13,muted,false);LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(5);c.addView(b,p);}if(click!=null)c.setOnClickListener(v->click.run());card(list,c);}
 protected int statusColor(String status){String s=status==null?"":status.toLowerCase(Locale.ROOT);if(s.contains("eligible")||s.contains("selected")||s.contains("accepted"))return success;if(s.contains("review")||s.contains("upcoming"))return warning;if(s.contains("reject")||s.contains("decline"))return Color.rgb(198,40,40);if(s.contains("shortlist"))return Color.rgb(105,75,160);return blue;}
 protected void navBar(String selected){LinearLayout n=row();n.setBackgroundColor(Color.WHITE);View divider=new View(this);divider.setBackgroundColor(line);root.addView(divider,lp(-1,1));String[] names={"Home","Drives","Applications","Profile"};String[] icons={String.valueOf((char)0x2302),String.valueOf((char)0x25cb),String.valueOf((char)0x25a4),String.valueOf((char)0x25ef)};Class<?>[] cs={DashboardActivity.class,PlacementDrivesActivity.class,ApplicationsActivity.class,ProfileActivity.class};for(int i=0;i<names.length;i++){final Class<?> c=cs[i];final String name=names[i];final int color=name.equals(selected)?blue:muted;LinearLayout cell=column();cell.setGravity(Gravity.CENTER);TextView icon=text(icons[i],18,color,true);icon.setGravity(Gravity.CENTER);cell.addView(icon);TextView label=text(name,10,color,true);label.setGravity(Gravity.CENTER);cell.addView(label);n.addView(cell,new LinearLayout.LayoutParams(0,dp(54),1));cell.setOnClickListener(v->{if(!getClass().equals(c)){Intent in=new Intent(this,c);in.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP);startActivity(in);}});}root.addView(n);}
 protected String extra(String key,String fallback){String s=getIntent().getStringExtra(key);return s==null?fallback:s;}
 protected void logout(){new AlertDialog.Builder(this).setTitle("Log out?").setMessage("This clears the local demo session.").setNegativeButton("Cancel",null).setPositiveButton("Log out",(d,w)->{DemoSession.logout();Intent i=new Intent(this,WelcomeActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);}).show();}
}
